using std::regex;
using std::string;
using std::smatch;
using std::regex_match;

regex R("(\\w+)");
string S("Match");
smatch m1, m2;

// Populate identical results
regex_match(S, m1, R);
regex_match(S, m2, R);

// Deep Comparison (ISO/IEC 14882:2014 Section 28.5.8.1)
// Checks:
// 1. m1.empty() == m2.empty()
// 2. Prefix/Suffix match
// 3. Size match (m1.size() == m2.size())
// 4. Content sequence match (std::equal on sub_matches)
bool are_identical = (m1 == m2); // True

smatch m3; // Empty result
bool identity_fail = (m1 == m3); // False (Fails Check 1)
